import { observer } from "mobx-react-lite";
import type { ReactNode } from "react";
import { presentationStore } from "../stores/PresentationStore";
import { DocumentHolder } from "./DocumentHolder";
import { FileMenu } from "./FileMenu/FileMenu";
import { AboutPanel } from "./LeftMenu/AboutPanel";
import { LeftMenu } from "./LeftMenu/LeftMenu";
import { RightMenu } from "./RightMenu/RightMenu";
import { StatusBar } from "./StatusBar/StatusBar";
import type { MonacoCommand } from "./Toolbar/MonacoCommand";
import { Toolbar } from "./Toolbar/Toolbar";

interface ViewportProps {
	toolbarVisible: boolean;
	statusbarVisible: boolean;
	leftMenuVisible: boolean;
	rightMenuVisible: boolean;
	isCompactToolbar: boolean;
	onMonacoCommand: (command: MonacoCommand) => void;
}

// Viewport reads presentationStore directly (file-menu panel, about panel) —
// it MUST be a mobx observer or those overlays never re-render: clicking the
// File tab flipped presentationStore.isFileMenuOpen yet .prese-file-menu-panel
// stayed display:none until some *other* observer (the App root reading
// isPresenting) happened to re-render the tree — and the same missing observer
// made the menu impossible to CLOSE (the Back click flipped the store but the
// panel stayed painted). Slide twin of the documented word/sheet File-menu bug.
const ViewportInner = function Viewport({
	toolbarVisible,
	statusbarVisible,
	leftMenuVisible,
	rightMenuVisible,
	isCompactToolbar,
	onMonacoCommand,
}: ViewportProps): ReactNode {
	const toolbarHeight = isCompactToolbar
		? "var(--wo-prese-toolbar-height-compact, 34px)"
		: "var(--wo-prese-toolbar-height, 40px)";

	return (
		<div className="prese-viewport">
			{/* File menu panel — full-screen overlay */}
			<section
				className="prese-file-menu-panel"
				style={{ display: presentationStore.isFileMenuOpen ? "block" : "none" }}
			>
				<FileMenu />
			</section>

			{/* Vertical layout: toolbar → body → statusbar */}
			<div className="prese-viewport-vbox">
				{/* Toolbar row */}
				{toolbarVisible && (
					<div
						className="prese-viewport-toolbar"
						style={{ height: toolbarHeight }}
						role="toolbar"
					>
						<Toolbar onMonacoCommand={onMonacoCommand} />
					</div>
				)}

				{/* Body row: left-menu | about-panel | editor | right-menu */}
				<div className="prese-viewport-body">
					{leftMenuVisible && (
						<div
							className="prese-viewport-left-menu"
							style={{
								// the rail grows by the panel width while one of its
								// toggles is active, pushing the canvas aside instead of
								// overflowing behind it (the fixed 40px inline width used
								// to clip every panel); About keeps its overlay below.
								width:
									presentationStore.activeLeftPanel !== null &&
									presentationStore.activeLeftPanel !== "about"
										? "calc(var(--wo-prese-leftmenu-width, 40px) + var(--wo-prese-leftpanel-width, 250px))"
										: "var(--wo-prese-leftmenu-width, 40px)",
							}}
						>
							<LeftMenu />
						</div>
					)}

					{/* About panel (overlay when about button is toggled) */}
					<div
						className="prese-about-menu-panel"
						style={{
							display:
								presentationStore.activeLeftPanel === "about"
									? "block"
									: "none",
						}}
					>
						<AboutPanel />
					</div>

					{/* Editor container */}
					<div className="prese-viewport-editor">
						<DocumentHolder />
					</div>

					{rightMenuVisible && (
						<div
							className="prese-viewport-right-menu"
							style={{ width: "var(--wo-prese-rightmenu-width, 40px)" }}
						>
							<RightMenu />
						</div>
					)}
				</div>

				{/* Statusbar row */}
				{statusbarVisible && (
					<div className="prese-viewport-statusbar">
						<StatusBar />
					</div>
				)}
			</div>
		</div>
	);
};

export const Viewport = observer(ViewportInner);
